INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Planung und Anforderungsanalyse > Kundenanforderungen formulieren
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Kundenanforderungen immer quantifizierbar formuliert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Qualitative Anforderungen sind ebenso gültig"}, {"text": "Ja", "correct": false, "because": "Quantifizierung ist nicht immer möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Kundenanforderungen ohne Rücksprache mit dem Kunden formuliert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundeninput ist essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Rücksprache fehlt Validität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind vage formulierte Kundenanforderungen für die Umsetzung ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Präzision ist für Klarheit nötig"}, {"text": "Ja", "correct": false, "because": "Vage Formulierungen führen zu Missverständnissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Dürfen Kundenanforderungen während eines Projekts unverändert bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassungen sind oft notwendig"}, {"text": "Ja", "correct": false, "because": "Statische Anforderungen sind unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Formulierung von Kundenanforderungen nur für technische Aspekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch nicht-technische Aspekte sind wichtig"}, {"text": "Ja", "correct": false, "because": "Umfassende Anforderungen gehen darüber hinaus"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Formulierung von Kundenanforderungen am wichtigsten?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Kürze", "correct": false, "because": "Kürze kann Präzision opfern"}, {"text": "Technische Detaillierung", "correct": false, "because": "Nicht immer primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft am besten, Kundenanforderungen präzise zu formulieren?', 2, '[{"text": "Interviews", "correct": true, "because": "Direkter Austausch klärt Details"}, {"text": "Brainstorming", "correct": false, "because": "Weniger strukturiert"}, {"text": "Prototyping", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler wird bei der Formulierung von Kundenanforderungen häufig übersehen?', 2, '[{"text": "Mehrdeutigkeit", "correct": true, "because": "Führt zu Interpretationsproblemen"}, {"text": "Übertechnisierung", "correct": false, "because": "Weniger häufig"}, {"text": "Zu hohe Kosten", "correct": false, "because": "Kein Formulierungsfehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Kunde bei der Formulierung seiner Anforderungen?', 3, '[{"text": "Aktiver Mitgestalter", "correct": true, "because": "Kundenwissen ist entscheidend"}, {"text": "Passiver Empfänger", "correct": false, "because": "Fehlende Mitwirkung schadet"}, {"text": "Kontrolleur", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument dient als Grundlage für formulierte Kundenanforderungen?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Bindend für Umsetzung"}, {"text": "Lastenheft", "correct": false, "because": "Vorläufiger Entwurf"}, {"text": "Projektplan", "correct": false, "because": "Zeitliche Steuerung"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Formulierung von Kundenanforderungen berücksichtigt werden?', 4, '[{"text": "Verständlichkeit", "correct": true, "because": "Für alle Beteiligten wichtig"}, {"text": "Nachprüfbarkeit", "correct": true, "because": "Erfüllung muss überprüfbar sein"}, {"text": "Realisierbarkeit", "correct": true, "because": "Muss technisch machbar sein"}, {"text": "Kreativität", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken eignen sich zur Formulierung von Kundenanforderungen?', 3, '[{"text": "Fragebögen", "correct": true, "because": "Strukturierte Datensammlung"}, {"text": "Workshops", "correct": true, "because": "Interaktive Klärung"}, {"text": "Beobachtung", "correct": true, "because": "Erkennt implizite Bedürfnisse"}, {"text": "Simulation", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können bei der Formulierung von Kundenanforderungen auftreten?', 3, '[{"text": "Unklare Begriffe", "correct": true, "because": "Führt zu Verwirrung"}, {"text": "Widersprüche", "correct": true, "because": "Verhindert Konsistenz"}, {"text": "Fehlende Priorisierung", "correct": true, "because": "Erschwert Umsetzung"}, {"text": "Zu viele Grafiken", "correct": false, "because": "Kein typischer Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen eine Kundenanforderung hochwertig?', 4, '[{"text": "Spezifisch", "correct": true, "because": "Vermeidet Vagheit"}, {"text": "Messbar", "correct": true, "because": "Erfüllung überprüfbar"}, {"text": "Zeitgebunden", "correct": true, "because": "Setzt Rahmen"}, {"text": "Inspirierend", "correct": false, "because": "Nicht primär nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Akteure sind an der Formulierung von Kundenanforderungen beteiligt?', 3, '[{"text": "Kunde", "correct": true, "because": "Liefert Bedürfnisse"}, {"text": "Fachinformatiker", "correct": true, "because": "Übersetzt in Technik"}, {"text": "Projektleiter", "correct": true, "because": "Koordiniert Prozess"}, {"text": "Lieferant", "correct": false, "because": "Später involviert"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenanforderungen sollten spezifisch sein. b) Sie dürfen nur technische Details enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezifität ja, nur Technik nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundenanforderungen werden im Pflichtenheft festgehalten. b) Sie müssen unveränderbar sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflichtenheft ja, Änderungen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenanforderungen sollten messbar sein. b) Der Kunde formuliert sie allein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Messbarkeit ja, Teamarbeit nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Workshops eignen sich zur Formulierung von Kundenanforderungen. b) Sie müssen immer schriftlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Workshops ja, Schrift nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenanforderungen müssen realisierbar sein. b) Sie werden nur vom Fachinformatiker geprüft.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Realisierbarkeit ja, Teamprüfung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

